<?php require 'config/bootstrap.php';$s=$pdo->prepare('SELECT p.*,u.nama,u.whatsapp wa,u.fakultas,u.prodi,t.id toko_id FROM produk p JOIN users u ON u.id=p.user_id LEFT JOIN toko t ON t.user_id=u.id WHERE p.id=?');$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Produk tidak ditemukan');}headpage('Detail produk');?><div class="panel p-4 row g-4"><?php if($p['gambar_produk']):?><div class="col-md-5"><img src="<?=e($p['gambar_produk'])?>" class="img-fluid rounded" alt=""></div><?php endif;?><div class="col"><h1><?=e($p['nama_produk'])?></h1><span class="badge bg-secondary"><?=e(str_replace('_',' ',$p['status_produk']))?></span><p class="mt-3"><?=nl2br(e($p['deskripsi_produk']))?></p><p>Penjual: <?=e($p['nama'])?> · <?=e($p['fakultas'])?> / <?=e($p['prodi'])?></p><?php $wa=preg_replace('/\D/','',$p['whatsapp']?:$p['wa']);if($wa):?><a class="btn btn-green" href="https://wa.me/<?=e($wa)?>" target="_blank" rel="noopener">Hubungi via WhatsApp</a><?php endif;?><?php if($p['toko_id']):?><a class="btn btn-outline-success" href="shop.php?id=<?=(int)$p['user_id']?>">Toko penjual</a><?php endif;?></div></div><?php footpage();